// Normaliza a resposta do PostgREST para um item por post.
// PostgREST GET retorna um JSON array como corpo de um único item n8n.
// Versões distintas do n8n podem entregar:
//   (a) item único com $json = [...] (array direto)
//   (b) item único com $json = { data: [...] }
//   (c) múltiplos itens individuais (HTTP node com splitIntoItems ativo)

const inputItems = $input.all();
let posts = [];

for (const item of inputItems) {
  const raw = item.json;
  if (Array.isArray(raw)) {
    // (a) array direto
    posts = posts.concat(raw);
  } else if (raw && Array.isArray(raw.data)) {
    // (b) encapsulado em .data
    posts = posts.concat(raw.data);
  } else if (raw && typeof raw.post_id === 'string') {
    // (c) item individual já splitado
    posts.push(raw);
  }
  // Ignorar itens malformados (sem post_id e sem array)
}

if (posts.length === 0) {
  console.log('[Split Posts] Nenhum post sem capa encontrado.');
  // Retornar item de controle para que o Resumo Final possa contabilizar
  return [{ json: { _workflow_control: true, status: 'nenhum_post', total: 0 } }];
}

console.log('[Split Posts] ' + posts.length + ' posts encontrados.');
return posts.map(function(p) { return { json: p }; });

// Prioridade: cover_source_url (derivada pelo workflow de Insights)
// Fallback: thumbnail_url, media_url (posts históricos sem cover_source_url)
const p = $input.item.json;
const coverUrl = p.cover_source_url || p.thumbnail_url || p.media_url || null;
return {
  json: {
    post_id:   p.post_id,
    username:  p.username,
    cover_url: coverUrl,
    has_url:   typeof coverUrl === 'string' && coverUrl.startsWith('http')
  }
};

// $json preserva os campos do item anterior (post_id, username, cover_url)
// $binary.data é preenchido pelo HTTP Request com responseFormat 'file'
const post   = $input.item.json;
const binary = $input.item.binary?.data;

if (!binary || !binary.mimeType) {
  return {
    json: {
      post_id:  post.post_id,
      username: post.username,
      ok:       false,
      status:   'erro_download',
      reason:   'sem_binario_ou_mime'
    }
  };
}

const MIME_EXT = {
  'image/jpeg': 'jpg',
  'image/jpg':  'jpg',
  'image/png':  'png',
  'image/webp': 'webp',
  'image/gif':  'gif'
};
const mime = binary.mimeType.split(';')[0].trim().toLowerCase();
const ext  = MIME_EXT[mime] || 'jpg';
const size = binary.fileSize || 0;

if (size > 5242880) {
  return {
    json: {
      post_id:   post.post_id,
      username:  post.username,
      ok:        false,
      status:    'erro_download',
      reason:    'arquivo_muito_grande',
      file_size: size
    }
  };
}

// Passar binary explicitamente para o próximo nó
return {
  json: {
    post_id:   post.post_id,
    username:  post.username,
    mime_type: mime,
    ext:       ext,
    file_size: size,
    ok:        true
  },
  binary: { data: binary }
};

// Montar paths e URL pública. Binary passado explicitamente.
const d       = $input.item.json;
const binary  = $input.item.binary?.data;
const baseUrl = $env.SUPABASE_URL;
const bucket  = 'instagram-covers';
const ext     = d.ext || 'jpg';
const mime    = d.mime_type || 'image/jpeg';

const storagePath = d.username + '/' + d.post_id + '.' + ext;
const publicUrl   = baseUrl + '/storage/v1/object/public/' + bucket + '/' + storagePath;
const uploadUrl   = baseUrl + '/storage/v1/object/' + bucket + '/' + storagePath;

return {
  json: {
    post_id:      d.post_id,
    username:     d.username,
    mime_type:    mime,
    ext:          ext,
    storage_path: storagePath,
    public_url:   publicUrl,
    upload_url:   uploadUrl
  },
  binary: { data: binary }
};

// $json aqui é a resposta HTTP do nó Upload (fullResponse:true)
// Os dados do post estão em $('Montar Caminho Storage').item.json
const resp    = $input.item.json;
const prev    = $('Montar Caminho Storage').item.json;
const status  = resp.statusCode || 0;
const ok      = status === 200 || status === 201;

if (!ok) {
  console.log('[Upload] Falha post_id=' + prev.post_id + ' HTTP=' + status);
  return {
    json: {
      post_id:     prev.post_id,
      username:    prev.username,
      ok:          false,
      status:      'erro_upload',
      http_status: status
    }
  };
}

return {
  json: {
    post_id:    prev.post_id,
    username:   prev.username,
    public_url: prev.public_url,
    ok:         true,
    http_status: status
  }
};

const resp       = $input.item.json;
const postId     = $('Verificar Upload').item.json.post_id;
const httpStatus = resp.statusCode || 0;
const body       = resp.body;
const rows       = Array.isArray(body) ? body : (body ? [body] : []);
const ok         = httpStatus === 200 && rows.length > 0;

if (!ok) {
  console.log('[PATCH] Falha post_id=' + postId + ' HTTP=' + httpStatus + ' rows=' + rows.length);
  return {
    json: {
      post_id:      postId,
      status:       'erro_patch',
      http_status:  httpStatus,
      rows_updated: rows.length
    }
  };
}

return {
  json: {
    post_id:      postId,
    status:       'sucesso',
    cover_url:    rows[0]?.cover_url || null,
    rows_updated: rows.length
  }
};

// Agrega todos os resultados de todos os caminhos.
// Cada item tem um campo 'status' definido pelos nós Tag ou Verificar.
const items = $input.all();

const counts = {
  total:         0,
  sucesso:       0,
  sem_url:       0,
  erro_download: 0,
  erro_upload:   0,
  erro_patch:    0
};
const erros = [];

for (const item of items) {
  const s = item.json?.status;
  // Ignorar item de controle gerado quando não há posts
  if (item.json?._workflow_control) continue;
  counts.total++;
  if      (s === 'sucesso')       counts.sucesso++;
  else if (s === 'sem_url')       counts.sem_url++;
  else if (s === 'erro_download') { counts.erro_download++; erros.push({ tipo: 'download', post_id: item.json?.post_id, reason: item.json?.reason }); }
  else if (s === 'erro_upload')   { counts.erro_upload++;   erros.push({ tipo: 'upload',   post_id: item.json?.post_id, http: item.json?.http_status }); }
  else if (s === 'erro_patch')    { counts.erro_patch++;    erros.push({ tipo: 'patch',    post_id: item.json?.post_id, http: item.json?.http_status }); }
}

console.log('[Resumo] ' + JSON.stringify({ counts, erros }, null, 2));

return {
  json: {
    executado_em: new Date().toISOString(),
    counts,
    erros
  }
};
